INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1224611-gs420', 'stk-eng.alwaleed', 'GS 420', 'info', '{"desc": "السلام عليكم …\n\nأنا منزل المادة هذا السمستر … واكتب هذا الرد قبل 45 دقيقة من الفاينل حق المادة …\n\nالمادة ما انصح فيها ابدا ابدا الا اذا كانت لغتك الانجليزيه مره كويسه … فيها كلمات كثيييييييرة جديدة وصعبه … يعني مذاكرتك تعتمد على مستوى لغتك …\n\nبالنسبة للدكتور أتعب وأنا اقول انه انسان عسل … متعاون لابعد درجة ويكفي انه يتعامل معك معاملة الأخ والصديق … ما تحس ان فيه اي حواجز بينك وبينه … ما يحاسب على الغياب لكن يقول اللي ما يغيب بأساعده اذا احتاج … الله يجزاه خير …\n\nباختصار المادة ما فيها اي كوز او هومورك … مجرد discussion في نهاية السمستر وتسوي عليها بريزنتيشن …\n\nلو بيدي كان نزلت مادة من المستوى الثاني او الثالث …\nالله يوفقك ويوفق الجميع …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/gs-420/144191/4", "user": "Eng.alwaleed", "ts": 1369022837000, "tid": 144191, "pn": 4}}', 1369022837000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
